class IconLogic extends DCLogic {
  renderVals() {
    const i = this.props.i ?? 'home';
    const s = Number(this.props.s ?? 48);
    const names = ['home','ticket','gift','user','scan','bell','receipt','shield','pin','share','chevR','chevD','chevL','arrowL','copy','check','lock','settings','help','wrench','chat','doc','logout','wallet','users','swap','star','eye','close','download','bag','store','coin','wheel','sidebar','menu','menuOpen','search','phone','mail','card','recycle','trash','clock','info','grid','moon','face','tag','map','box','plus','external','camera','warn'];
    const is = {};
    names.forEach((n) => { is[n] = n === i; });
    return {
      is,
      sw: String(this.props.w ?? 1.8),
      box: 'display:inline-flex;flex:none;width:' + s + 'px;height:' + s + 'px;line-height:0;'
    };
  }
}

window.IconLogic = IconLogic;

