    const move = (x, y, ev) => {
      if (!g) return;
      const dx = x - g.x, dy = y - g.y;
      if (!g.axis) { if (Math.abs(dx) < 10 && Math.abs(dy) < 10) return; g.axis = Math.abs(dx) > Math.abs(dy) * 1.3 ? 'x' : 'y'; if (g.axis === 'y') { g = null; return; } }
      if (ev && ev.cancelable) ev.preventDefault();
      const edge = (dx > 0 && g.i === 0) || (dx < 0 && g.i === g.btns.length - 1);
      g.dx = dx;
      const k = edge ? 0.15 : 0.45;
      g.els.forEach((e) => { e.style.transition = 'none'; e.style.translate = (dx * k) + 'px 0'; e.style.opacity = String(1 - Math.min(0.35, Math.abs(dx) / 900)); });
    };
    const end = (x) => {
      if (!g) return;
      const cur = g; g = null;
      if (cur.axis !== 'x') return;
      const v = Math.abs(cur.dx) / Math.max(1, Date.now() - cur.t);
      const dir = cur.dx < 0 ? 1 : -1;
      const to = cur.i + dir;
      const go = (Math.abs(cur.dx) > 60 || v > 0.45) && to >= 0 && to < cur.btns.length;
      const reset = (e) => { e.style.transition = ''; e.style.translate = ''; e.style.opacity = ''; };
      if (!go) {
        suppress = true; setTimeout(() => { suppress = false; }, 350);
        cur.els.forEach((e) => { if (e.animate && !reduce()) e.animate([{ translate: e.style.translate, opacity: e.style.opacity || 1 }, { translate: '0 0', opacity: 1 }], { duration: 260, easing: 'cubic-bezier(.2,.85,.25,1)' }); reset(e); });
        return;
      }
      cur.els.forEach(reset);
      cur.btns[to].click();
      // swallow the click the browser sends after a mouse drag
      suppress = true; setTimeout(() => { suppress = false; }, 350);
      if (reduce()) return;
      requestAnimationFrame(() => requestAnimationFrame(() => {
        const seg = tabsOf(); if (!seg) return;
        after(seg).forEach((e) => { if (e.animate) e.animate([{ translate: (dir * 70) + 'px 0', opacity: 0 }, { translate: '0 0', opacity: 1 }], { duration: 320, easing: 'cubic-bezier(.2,.85,.25,1)' }); });
      }));
    };
